INSERT INTO fut_tactics VALUES(1,'2026-09-27T14:20','bXzdq$2TXb5b','Default Tactic','4-2-3-1 (2)','4','Balanced','Balanced',50,1,33,'AVL',NULL,'인게임 실측(사용자 보고 2026-09-27T14:20 「계속 지원이었는데」) — ST 포커스만 정정. 나머지 10칸은 직전 회차(fut.gg 본문) 값을 이월했다.','MEASURED(사용자 인게임 확인) — ⛔⛔ **fut.gg 표기와 충돌한다**: fut.gg는 17분 전 싱크 기준으로도 ST를 `Versatile`로 보여 줬고 우리 회차 기록(09-26·09-27T08:07·T11:46)이 전부 그 값을 옮긴 것이다. 불변규칙 3대로 **인게임 실측을 채택**한다. ⚠️ 한 칸이 틀렸다면 **나머지 10칸도 의심 대상**이다 — 그 열 칸은 아직 인게임으로 확인하지 못했으므로 이월값이고, 다음 회차에 전수 확인해야 한다.');
INSERT INTO fut_tactics VALUES(1,'2026-09-27T15:10','bXzdq$2TXb5b','Default Tactic','4-2-3-1 (2)','4','Short Passing','Balanced',52,1,33,'AVL',NULL,'인게임 실측(사용자 보고 2026-09-27T15:10 「빌드업스타일 짧은 패스 수비라인 52로 변경」) — 빌드업 Balanced→Short Passing · 라인 50→52. 나머지 항목은 직전 회차 이월.','MEASURED(사용자 인게임 변경 보고) — 11칸 역할/포커스·전술 코드는 직전 회차 이월값이다. ⚠️ 전술 코드는 설정이 바뀌면 함께 바뀔 것이므로 **다음 fut.gg 싱크에서 재판독**해야 한다 (코드가 빌드업·라인을 인코딩한다 — 09-26 실측에서 역할 두 칸 변경이 코드 두 글자로 나타났다). ⛔ 지금 코드를 그대로 이월한 것은 **아직 못 읽었기 때문**이지 안 바뀌었다는 뜻이 아니다.');
INSERT INTO fut_tactics VALUES(1,'2026-09-27T17:05','yYKAB8NquSeS','Default Tactic','4-2-3-1 (2)','4','Balanced','Balanced',52,1,33,'AVL',NULL,'fut.gg GG Club 전술 상세 페이지 본문(/gg-club/ho6/tactics/2568732-0_tactic-0 · 2026-09-27T17:05 club-sync §3-3 수동 확인) · 케미는 /gg-club/ho6/squads/ 표기 33/33','HIGH(페이지 표기) — 직전 행(2026-09-27T15:10)과 비교해 네 곳이 바뀌었다: GK 역할 Ball Playing Keeper→Goalkeeper · GK 포커스 Build-Up→Balanced · ST 포커스 Support→Versatile · 빌드업 Short Passing→Balanced(라인 52 동일). ⚠️ 전술 코드가 세 값으로 갈린다 — 페이지 본문 yYKAB8NquSeS · 같은 회차 /api/gg-club/active-squad/ 응답 1YNDE@Qtx1jV · 직전 원장 행 bXzdq$2TXb5b. 페이지 본문을 채택했다(런북 §3-3의 확인 경로). ⚠️ API는 같은 회차에 buildUpStyleId=4를 줬는데 페이지는 Balanced로 적는다 — 이 충돌은 해소하지 못했다. ⚠️ 서버 렌더라 role_ea_id·last_updated_at은 얻을 수 없어 결손으로 둔다.');
INSERT INTO fut_tactics VALUES(1,'2026-09-28T12:30','6YS#BEVk2ama','Default Tactic','4-2-3-1 (2)','4','Balanced','Balanced',52,1,33,'AVL','2026-09-28T03:27:04.491725Z','fut.gg GG Club 전술 상세 페이지 본문(/gg-club/ho6/tactics/2568732-0_tactic-0 · 2026-09-28T12:30 club-sync §3-3) + 같은 회차 /api/gg-club/active-squad/ activeTactic(code·positionRoles.roleId·lastUpdatedAt) · 케미는 /gg-club/ho6/squads/ 표기 33/33','HIGH(페이지·API 일치) — 직전 행(2026-09-27T17:05)과 비교해 두 곳이 바뀌었다: LB Attacking Wingback/Support→Wingback/Balanced · LM Inside Forward 포커스 Attack→Balanced. 전술 코드는 페이지·API 모두 6YS#BEVk2ama로 일치(직전 행의 3값 갈림은 이번 회차엔 없음). ⭐ role_ea_id·last_updated_at은 active-squad API의 activeTactic에서 얻었다(런북의 「얻을 수 없다」는 페이지 경로 한정). positionUniqueId(0,3,4,6,7,9,11,12,16,18,25)를 순서대로 슬롯 0~10에 대응시켰고 페이지 표기 역할명과 대조해 모두 맞았다.');
